+
+        try {
+            byte[] bytes = IOUtils.toByteArray(getClass().getResourceAsStream("/multiple.gz"));
+
+            // Let's feed the input byte by byte to simulate fragmentation.
+            ByteBuf buf = Unpooled.copiedBuffer(bytes);
